/**
 * Unit tests for MultiplePiePlot.setPieChart.
 */
public class MultiplePiePlot_setPieChart_TriageGen0Test {

    private MultiplePiePlot multiplePiePlot;

    @Before
    public void setUp() {
        multiplePiePlot = new MultiplePiePlot();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetPieChart_NullArgument() {
        multiplePiePlot.setPieChart(null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetPieChart_WrongPlotType() {
        // Create a chart that does not have a PiePlot (e.g., a BarChart or a generic JFreeChart)
        // Since we cannot easily instantiate a generic JFreeChart without a dataset, 
        // we use a Chart that uses a different Plot type.
        // For the sake of this test, we mock/create a chart with a different plot.
        // Using a XYPlot or similar via a different chart type.

        // Note: In JFreeChart, most charts are created via ChartFactory. 
        // Here we simulate a chart where getPlot() returns something other than PiePlot.
        JFreeChart nonPieChart = new JFreeChart("Non-Pie Chart", new DefaultPieDataset(), null) {
            @Override
            public org.jfree.chart.plot.Plot getPlot() {
                // Return a dummy plot that is NOT a PiePlot
                return new org.jfree.chart.plot.XYPlot(null, null, null, null);
            }
        };

        multiplePiePlot.setPieChart(nonPieChart);
    }

    @Test
    public void testSetPieChart_Success() {
        // Create a valid PieChart
        DefaultPieDataset dataset = new DefaultPieDataset();
        dataset.setValue("A", 1.0);
        PieChart pieChart = new PieChart("Test Chart", dataset, new PiePlot());

        // Verify the plot is indeed a PiePlot to satisfy the method condition
        assertNotNull(pieChart.getPlot());
        assertEquals(true, pieChart.getPlot() instanceof PiePlot);

        // Execute the method under test
        multiplePiePlot.setPieChart(pieChart);

        // Verify the result
        assertEquals(pieChart, multiplePiePlot.getPieChart());
    }
}
